window.CODIGO_JAVA = window.CODIGO_JAVA || {};
window.CODIGO_JAVA["reportes-ejecutivos-ms"] = {"src/main/java/com/mx/josesaid/develop/reportes/ReportesEjecutivosApplication.java": "package com.mx.josesaid.develop.reportes;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de reportes-ejecutivos-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class ReportesEjecutivosApplication {\n\n    /** Arranca reportes-ejecutivos-ms. */\n    public static void main(String[] args) {\n        SpringApplication.run(ReportesEjecutivosApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/api/ManejadorErrores.java": "package com.mx.josesaid.develop.reportes.api;\n\nimport com.mx.josesaid.develop.reportes.domain.ConflictoException;\nimport com.mx.josesaid.develop.reportes.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.reportes.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.reportes.domain.SolicitudInvalidaException;\nimport java.net.URI;\nimport org.springframework.dao.OptimisticLockingFailureException;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/** Convierte excepciones en respuestas RFC 9457 (application/problem+json). */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    /** Convierte una regla de negocio incumplida en 422. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ResponseEntity<ProblemDetail> reglaDeNegocio(ReglaDeNegocioException e) {\n        return respuesta(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", e.getMessage());\n    }\n\n    /** Convierte un recurso inexistente en 404. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ResponseEntity<ProblemDetail> noEncontrado(RecursoNoEncontradoException e) {\n        return respuesta(HttpStatus.NOT_FOUND, \"recurso-no-encontrado\", e.getMessage());\n    }\n\n    /** Convierte un conflicto, por ejemplo modificar un reporte cerrado, en 409. */\n    @ExceptionHandler(ConflictoException.class)\n    ResponseEntity<ProblemDetail> conflicto(ConflictoException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-de-estado\", e.getMessage());\n    }\n\n    /** Convierte una solicitud inválida en 400. */\n    @ExceptionHandler(SolicitudInvalidaException.class)\n    ResponseEntity<ProblemDetail> solicitudInvalida(SolicitudInvalidaException e) {\n        return respuesta(HttpStatus.BAD_REQUEST, \"solicitud-invalida\", e.getMessage());\n    }\n\n    /** Convierte un conflicto de concurrencia (dos cambios al mismo registro a la vez) en 409. El cliente debe reintentar. */\n    @ExceptionHandler(OptimisticLockingFailureException.class)\n    ResponseEntity<ProblemDetail> concurrencia(OptimisticLockingFailureException e) {\n        return respuesta(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"El registro cambió mientras se procesaba. Vuelva a leerlo e intente de nuevo.\");\n    }\n\n    /** Construye la respuesta de error con el estado, el tipo y el detalle indicados. */\n    private static ResponseEntity<ProblemDetail> respuesta(HttpStatus estado, String slug, String detalle) {\n        ProblemDetail problema = ProblemDetail.forStatusAndDetail(estado, detalle);\n        problema.setTitle(estado.getReasonPhrase());\n        problema.setType(URI.create(\"urn:josesaid:reportes-ejecutivos:error:\" + slug));\n        return ResponseEntity.status(estado).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(problema);\n    }\n\n    /** Convierte parámetros inválidos en 400 con el detalle de cada campo. */\n    @org.springframework.web.bind.annotation.ExceptionHandler(jakarta.validation.ConstraintViolationException.class)\n    org.springframework.http.ProblemDetail parametrosInvalidos(jakarta.validation.ConstraintViolationException e) {\n        return org.springframework.http.ProblemDetail.forStatusAndDetail(\n                org.springframework.http.HttpStatus.BAD_REQUEST, \"Revise los parámetros indicados\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/api/ReportesControlador.java": "package com.mx.josesaid.develop.reportes.api;\n\nimport com.mx.josesaid.develop.reportes.application.ReportesService;\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.EstatusReporte;\nimport com.mx.josesaid.develop.reportes.domain.Indicador;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport com.mx.josesaid.develop.reportes.domain.Reporte;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpHeaders;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;\nimport org.springframework.web.server.ResponseStatusException;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RestController;\nimport jakarta.validation.constraints.Size;\nimport org.springframework.validation.annotation.Validated;\n\n/**\n * API de reportes. Casi toda la API es de DIRECCION; la consulta también acepta JEFE_AREA, limitada a su área. La carga principal de indicadores es por Kafka;\n * POST /indicadores existe para cargas manuales y correcciones.\n */\n@Validated\n@RestController\n@RequestMapping(\"/v1\")\npublic class ReportesControlador {\n\n    private final ReportesService servicio;\n\n    /** Recibe el servicio de reportes. El controlador no contiene reglas de negocio. */\n    public ReportesControlador(ReportesService servicio) {\n        this.servicio = servicio;\n    }\n\n    /** Registra un indicador de un área para un periodo. Si el periodo no existe, lo abre. Un periodo cerrado responde 409. Solo puede hacerlo DIRECCION. */\n    @PostMapping(\"/indicadores\")\n    @PreAuthorize(\"hasRole('DIRECCION')\")\n    public ResponseEntity<IndicadorRespuesta> registrarIndicador(@Valid @RequestBody RegistrarIndicadorPeticion p) {\n        Indicador i = servicio.registrarIndicador(p.area(), p.nombre(), Periodo.de(p.periodo()),\n                p.valor(), p.fuenteActualizadaUtc());\n        return ResponseEntity.status(HttpStatus.CREATED).body(IndicadorRespuesta.de(i, false));\n    }\n\n    /** DIRECCION consulta cualquier área. JEFE_AREA solo la suya, según el claim {@code area} del token. */\n    @GetMapping(\"/indicadores\")\n    @PreAuthorize(\"hasAnyRole('DIRECCION','JEFE_AREA')\")\n    public List<IndicadorRespuesta> consultarIndicadores(@RequestParam(required = false) Area area,\n                                                         @RequestParam @Size(max = 20) String periodo,\n                                                         Authentication autenticacion) {\n        return servicio.consultarIndicadores(alcance(area, autenticacion), Periodo.de(periodo)).stream()\n                .map(v -> IndicadorRespuesta.de(v.indicador(), v.desactualizado()))\n                .toList();\n    }\n\n    /** Limita el área consultada a la del usuario, salvo que sea de dirección. Así cada área solo ve sus indicadores. */\n    private static Area alcance(Area solicitada, Authentication autenticacion) {\n        boolean direccion = autenticacion.getAuthorities().stream()\n                .anyMatch(a -> \"ROLE_DIRECCION\".equals(a.getAuthority()));\n        if (direccion) {\n            return solicitada;\n        }\n        String claim = autenticacion instanceof JwtAuthenticationToken jwt\n                ? jwt.getToken().getClaimAsString(\"area\") : null;\n        Area propia;\n        try {\n            propia = claim == null ? null : Area.valueOf(claim);\n        } catch (IllegalArgumentException e) {\n            propia = null;\n        }\n        if (propia == null) {\n            throw new ResponseStatusException(HttpStatus.FORBIDDEN, \"El usuario no tiene un área válida asignada\");\n        }\n        if (solicitada != null && solicitada != propia) {\n            throw new ResponseStatusException(HttpStatus.FORBIDDEN, \"Solo puede consultar indicadores de su área\");\n        }\n        return propia;\n    }\n\n    /** DIRECCION ve el reporte completo. JEFE_AREA ve solo los indicadores de su área. */\n    @GetMapping(\"/reportes/{periodo}\")\n    @PreAuthorize(\"hasAnyRole('DIRECCION','JEFE_AREA')\")\n    public ReporteRespuesta consultarReporte(@PathVariable String periodo, Authentication autenticacion) {\n        ReportesService.ReporteVista v = servicio.consultarReporte(Periodo.de(periodo));\n        Area alcance = alcance(null, autenticacion);\n        List<IndicadorConsolidado> indicadores = alcance == null ? v.indicadores()\n                : v.indicadores().stream().filter(i -> i.area() == alcance).toList();\n        return ReporteRespuesta.de(v.reporte(), indicadores);\n    }\n\n    /** Cierra el reporte del periodo: consolida los indicadores y no admite más cambios. Solo puede hacerlo DIRECCION. */\n    @PostMapping(\"/reportes/{periodo}/cierre\")\n    @PreAuthorize(\"hasRole('DIRECCION')\")\n    public ReporteRespuesta cerrarReporte(@PathVariable String periodo) {\n        servicio.cerrarReporte(Periodo.de(periodo));\n        ReportesService.ReporteVista v = servicio.consultarReporte(Periodo.de(periodo));\n        return ReporteRespuesta.de(v.reporte(), v.indicadores());\n    }\n\n    /** Exporta el reporte en CSV, PDF o XLSX. Devuelve el archivo con su nombre y tipo MIME. */\n    @GetMapping(\"/reportes/{id}/exportacion\")\n    @PreAuthorize(\"hasRole('DIRECCION')\")\n    public ResponseEntity<byte[]> exportar(@PathVariable UUID id, @RequestParam(defaultValue = \"CSV\") @Size(max = 10) String formato) {\n        ReportesService.Exportacion e = servicio.exportar(id, formato);\n        return ResponseEntity.ok()\n                .header(HttpHeaders.CONTENT_DISPOSITION, \"attachment; filename=\\\"\" + e.nombreArchivo() + \"\\\"\")\n                .contentType(MediaType.parseMediaType(e.formato().mediaType()))\n                .body(e.contenido());\n    }\n\n    // ---- Peticiones ----\n\n    /**\n     * Cuerpo para registrar un indicador: área, nombre, periodo, valor y fecha de la fuente.\n     *\n     * @param area componente de tipo {@code Area}.\n     * @param nombre componente de tipo {@code String}.\n     * @param periodo componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     */\n    public record RegistrarIndicadorPeticion(\n            @NotNull Area area,\n            @NotBlank String nombre,\n            @NotBlank String periodo,\n            @NotNull BigDecimal valor,\n            @NotNull Instant fuenteActualizadaUtc) {\n    }\n\n    // ---- Respuestas ----\n\n    /**\n     * Indicador tal como lo ve el cliente. Marca si la fuente está desactualizada.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param area componente de tipo {@code Area}.\n     * @param nombre componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param periodo componente de tipo {@code String}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     * @param desactualizado componente de tipo {@code boolean}.\n     */\n    public record IndicadorRespuesta(UUID id, Area area, String nombre, BigDecimal valor, String periodo,\n                                     Instant fuenteActualizadaUtc, boolean desactualizado) {\n        /** Convierte un indicador del dominio en su respuesta. */\n        static IndicadorRespuesta de(Indicador i, boolean desactualizado) {\n            return new IndicadorRespuesta(i.id(), i.area(), i.nombre(), i.valor(), i.periodo().clave(),\n                    i.fuenteActualizadaUtc(), desactualizado);\n        }\n    }\n\n    /**\n     * Indicador consolidado de un reporte cerrado.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param area componente de tipo {@code Area}.\n     * @param nombre componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     * @param desactualizado componente de tipo {@code boolean}.\n     */\n    public record IndicadorConsolidadoRespuesta(UUID id, Area area, String nombre, BigDecimal valor,\n                                                Instant fuenteActualizadaUtc, boolean desactualizado) {\n        /** Convierte un indicador consolidado del dominio en su respuesta. */\n        static IndicadorConsolidadoRespuesta de(IndicadorConsolidado c) {\n            return new IndicadorConsolidadoRespuesta(c.id(), c.area(), c.nombre(), c.valor(),\n                    c.fuenteActualizadaUtc(), c.desactualizado());\n        }\n    }\n\n    /**\n     * Reporte con sus indicadores. Si está cerrado, incluye los consolidados.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param periodo componente de tipo {@code String}.\n     * @param estatus componente de tipo {@code EstatusReporte}.\n     * @param creadoUtc componente de tipo {@code Instant}.\n     * @param cerradoUtc componente de tipo {@code Instant}.\n     * @param indicadores componente de tipo {@code List<IndicadorConsolidadoRespuesta>}.\n     */\n    public record ReporteRespuesta(UUID id, String periodo, EstatusReporte estatus, Instant creadoUtc,\n                                   Instant cerradoUtc, List<IndicadorConsolidadoRespuesta> indicadores) {\n        /** Convierte un reporte del dominio en su respuesta. */\n        static ReporteRespuesta de(Reporte r, List<IndicadorConsolidado> indicadores) {\n            return new ReporteRespuesta(r.getId(), r.getPeriodo().clave(), r.getEstatus(), r.getCreadoUtc(),\n                    r.getCerradoUtc(), indicadores.stream().map(IndicadorConsolidadoRespuesta::de).toList());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/DatosExportacion.java": "package com.mx.josesaid.develop.reportes.application;\n\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport java.util.List;\nimport java.util.UUID;\n\n/**\n * Datos que un exportador necesita. No depende de JPA ni de ningún formato.\n *\n * @param reporteId componente de tipo {@code UUID}.\n * @param periodo componente de tipo {@code String}.\n * @param indicadores componente de tipo {@code List<IndicadorConsolidado>}.\n */\npublic record DatosExportacion(UUID reporteId, String periodo, List<IndicadorConsolidado> indicadores) {\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/EventoDominio.java": "package com.mx.josesaid.develop.reportes.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo componente de tipo {@code String}.\n * @param agregadoId componente de tipo {@code String}.\n * @param datos componente de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/ExportadorReporte.java": "package com.mx.josesaid.develop.reportes.application;\n\n/** Puerto de exportación. Cada formato tiene su implementación en infrastructure/exportacion. */\npublic interface ExportadorReporte {\n\n    FormatoExportacion formato();\n\n    byte[] exportar(DatosExportacion datos);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/FormatoExportacion.java": "package com.mx.josesaid.develop.reportes.application;\n\nimport com.mx.josesaid.develop.reportes.domain.SolicitudInvalidaException;\n\n/** Formatos de exportación de un reporte. CSV es el valor por omisión. */\npublic enum FormatoExportacion {\n    CSV(\"text/csv;charset=UTF-8\", \"csv\"),\n    PDF(\"application/pdf\", \"pdf\"),\n    XLSX(\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\", \"xlsx\");\n\n    private final String mediaType;\n    private final String extension;\n\n    FormatoExportacion(String mediaType, String extension) {\n        this.mediaType = mediaType;\n        this.extension = extension;\n    }\n\n    /** Tipo MIME del archivo que se devuelve al cliente. */\n    public String mediaType() {\n        return mediaType;\n    }\n\n    /** Extensión del archivo exportado, sin punto. */\n    public String extension() {\n        return extension;\n    }\n\n    /** Acepta el nombre sin distinguir mayúsculas. Otro valor es 400. */\n    public static FormatoExportacion desde(String valor) {\n        if (valor != null) {\n            for (FormatoExportacion f : values()) {\n                if (f.name().equalsIgnoreCase(valor.trim())) {\n                    return f;\n                }\n            }\n        }\n        throw new SolicitudInvalidaException(\"Formato no soportado: \" + valor + \". Disponibles: CSV, PDF, XLSX\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/PublicadorEventos.java": "package com.mx.josesaid.develop.reportes.application;\n\n/** Publica los eventos de dominio de reportes, como reporte-cerrado, para que otros servicios reaccionen. */\npublic interface PublicadorEventos {\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/application/ReportesService.java": "package com.mx.josesaid.develop.reportes.application;\n\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.EstatusReporte;\nimport com.mx.josesaid.develop.reportes.domain.Indicador;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorRepositorio;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport com.mx.josesaid.develop.reportes.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.reportes.domain.Reporte;\nimport com.mx.josesaid.develop.reportes.domain.ReporteRepositorio;\nimport io.micrometer.core.instrument.MeterRegistry;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.EnumMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Consolidación de indicadores, cierre de reportes y exportación. */\n@Service\npublic class ReportesService {\n\n    private final IndicadorRepositorio indicadores;\n    private final ReporteRepositorio reportes;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n    private final MeterRegistry metricas;\n    private final Duration frescura;\n    private final Map<FormatoExportacion, ExportadorReporte> exportadores = new EnumMap<>(FormatoExportacion.class);\n\n    /** Recibe los repositorios, el publicador de eventos, los exportadores por formato, las métricas y el reloj. */\n    public ReportesService(IndicadorRepositorio indicadores, ReporteRepositorio reportes, PublicadorEventos eventos,\n                           Clock reloj, MeterRegistry metricas,\n                           @Value(\"${reportes.frescura-dias:7}\") int frescuraDias,\n                           List<ExportadorReporte> listaExportadores) {\n        this.indicadores = indicadores;\n        this.reportes = reportes;\n        this.eventos = eventos;\n        this.reloj = reloj;\n        this.metricas = metricas;\n        this.frescura = Duration.ofDays(frescuraDias);\n        listaExportadores.forEach(e -> this.exportadores.put(e.formato(), e));\n    }\n\n    /**\n     * Indicador con la marca de si su fuente está desactualizada.\n     *\n     * @param indicador componente de tipo {@code Indicador}.\n     * @param desactualizado componente de tipo {@code boolean}.\n     */\n    public record IndicadorVista(Indicador indicador, boolean desactualizado) {\n    }\n\n    /**\n     * Reporte con sus indicadores consolidados.\n     *\n     * @param reporte componente de tipo {@code Reporte}.\n     * @param indicadores componente de tipo {@code List<IndicadorConsolidado>}.\n     */\n    public record ReporteVista(Reporte reporte, List<IndicadorConsolidado> indicadores) {\n    }\n\n    /**\n     * Resultado de exportar: contenido binario, formato y nombre de archivo sugerido.\n     *\n     * @param contenido componente de tipo {@code byte[]}.\n     * @param formato componente de tipo {@code FormatoExportacion}.\n     * @param nombreArchivo componente de tipo {@code String}.\n     */\n    public record Exportacion(byte[] contenido, FormatoExportacion formato, String nombreArchivo) {\n    }\n\n    /** Registra un indicador en el periodo. Si el reporte no existe lo abre; si ya está cerrado, la operación se rechaza. */\n    @Transactional\n    public Indicador registrarIndicador(Area area, String nombre, Periodo periodo, BigDecimal valor, Instant fuente) {\n        Reporte reporte = reportes.buscarPorPeriodo(periodo).orElseGet(() -> Reporte.abrir(periodo, Instant.now(reloj)));\n        reporte.exigirAbierto();\n        reportes.guardar(reporte);\n        Indicador guardado = indicadores.guardar(Indicador.nuevo(area, nombre, periodo, valor, fuente));\n        metricas.counter(\"indicadores.recibidos\").increment();\n        return guardado;\n    }\n\n    /** Devuelve los indicadores de un área y periodo, marcando los que tienen fuente desactualizada. */\n    @Transactional(readOnly = true)\n    public List<IndicadorVista> consultarIndicadores(Area area, Periodo periodo) {\n        Instant ahora = Instant.now(reloj);\n        return indicadores.buscar(area, periodo).stream()\n                .map(i -> new IndicadorVista(i, i.desactualizado(ahora, frescura)))\n                .toList();\n    }\n\n    /** Devuelve el reporte de un periodo con sus indicadores. */\n    @Transactional(readOnly = true)\n    public ReporteVista consultarReporte(Periodo periodo) {\n        Reporte r = cargarPorPeriodo(periodo);\n        return new ReporteVista(r, indicadoresDe(r));\n    }\n\n    /** Cierra el reporte del periodo y publica el evento reporte-cerrado. Si el reporte no tiene indicadores, la operación se rechaza. */\n    @Transactional\n    public Reporte cerrarReporte(Periodo periodo) {\n        Reporte r = cargarPorPeriodo(periodo);\n        Instant ahora = Instant.now(reloj);\n        r.cerrar(indicadoresDe(r), ahora);\n        Reporte guardado = reportes.guardar(r);\n        metricas.counter(\"reportes.cerrados\").increment();\n        eventos.publicar(new EventoDominio(\"reporte-cerrado\", guardado.getId().toString(), Map.of(\n                \"id\", guardado.getId().toString(),\n                \"periodo\", periodo.clave())));\n        return guardado;\n    }\n\n    /** Exporta el reporte en CSV, PDF o XLSX. Un formato desconocido responde 400. */\n    @Transactional(readOnly = true)\n    public Exportacion exportar(UUID id, String formato) {\n        FormatoExportacion f = FormatoExportacion.desde(formato);\n        Reporte r = buscarReporte(id);\n        byte[] contenido = exportadores.get(f).exportar(\n                new DatosExportacion(r.getId(), r.getPeriodo().clave(), indicadoresDe(r)));\n        String nombre = \"reporte-\" + r.getPeriodo().clave() + \".\" + f.extension();\n        return new Exportacion(contenido, f, nombre);\n    }\n\n    /** Busca un reporte por su identificador. Si no existe, lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public Reporte buscarReporte(UUID id) {\n        return reportes.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Reporte no encontrado: \" + id));\n    }\n\n    /** Reporte cerrado: foto guardada. Reporte abierto: consolidado en vivo. */\n    private List<IndicadorConsolidado> indicadoresDe(Reporte r) {\n        if (r.getEstatus() == EstatusReporte.CERRADO) {\n            return r.getIndicadoresCerrados();\n        }\n        Instant ahora = Instant.now(reloj);\n        return indicadores.buscar(null, r.getPeriodo()).stream()\n                .map(i -> new IndicadorConsolidado(i.id(), i.area(), i.nombre(), i.valor(),\n                        i.fuenteActualizadaUtc(), i.desactualizado(ahora, frescura)))\n                .toList();\n    }\n\n    /** Busca un reporte por periodo. Si no existe, lanza RecursoNoEncontradoException. */\n    private Reporte cargarPorPeriodo(Periodo periodo) {\n        return reportes.buscarPorPeriodo(periodo)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"No existe reporte para el periodo \" + periodo));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.reportes.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code reportes.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"reportes.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/config/RelojConfig.java": "package com.mx.josesaid.develop.reportes.config;\n\nimport java.time.Clock;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC. Todas las fechas de reportes se calculan con este reloj. */\n    @Bean\n    Clock reloj() {\n        return Clock.systemUTC();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/config/SeguridadConfig.java": "package com.mx.josesaid.develop.reportes.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.reportes.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.reportes.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.reportes.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad: exige JWT válido y reglas por rol para cada endpoint. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt para el servicio. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/Area.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** Áreas que reportan indicadores. Cada área es dueña de sus datos; este servicio solo consolida. */\npublic enum Area {\n    VENTAS_ATENCION_CLIENTES(\"Ventas y atención a clientes\"),\n    FINANZAS_CONTABILIDAD(\"Finanzas y contabilidad\"),\n    OPERACIONES(\"Operaciones\"),\n    COMPRAS_PROVEEDORES(\"Compras y proveedores\"),\n    ADMINISTRACION_LEGAL(\"Administración y legal\"),\n    DIRECCION_GENERAL(\"Dirección general\");\n\n    private final String etiqueta;\n\n    Area(String etiqueta) {\n        this.etiqueta = etiqueta;\n    }\n\n    /** Etiqueta legible del área, para mostrarla en pantalla y en exportaciones. */\n    public String etiqueta() {\n        return etiqueta;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/ConflictoException.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** Conflicto con el estado actual del reporte. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Crea la excepción con el motivo del conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/EstatusReporte.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** Estados del reporte: BORRADOR mientras se puede modificar y CERRADO cuando ya no admite cambios. */\npublic enum EstatusReporte { BORRADOR, CERRADO }\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/Indicador.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.math.BigDecimal;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Valor de un indicador de un área en un periodo. Se identifica por área, nombre y periodo.\n *\n * @param id componente de tipo {@code UUID}.\n * @param area componente de tipo {@code Area}.\n * @param nombre componente de tipo {@code String}.\n * @param valor componente de tipo {@code BigDecimal}.\n * @param periodo componente de tipo {@code Periodo}.\n * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n */\npublic record Indicador(UUID id, Area area, String nombre, BigDecimal valor, Periodo periodo,\n                        Instant fuenteActualizadaUtc) {\n\n    public Indicador {\n        if (area == null) {\n            throw new SolicitudInvalidaException(\"El área es obligatoria\");\n        }\n        if (nombre == null || nombre.isBlank()) {\n            throw new SolicitudInvalidaException(\"El nombre del indicador es obligatorio\");\n        }\n        if (valor == null) {\n            throw new SolicitudInvalidaException(\"El valor es obligatorio\");\n        }\n        if (periodo == null) {\n            throw new SolicitudInvalidaException(\"El periodo es obligatorio\");\n        }\n        if (fuenteActualizadaUtc == null) {\n            throw new SolicitudInvalidaException(\"La fecha de actualización de la fuente es obligatoria\");\n        }\n        nombre = nombre.trim();\n    }\n\n    /** Crea un indicador nuevo. La fecha de la fuente se guarda para detectar datos desactualizados. */\n    public static Indicador nuevo(Area area, String nombre, Periodo periodo, BigDecimal valor, Instant fuente) {\n        return new Indicador(UUID.randomUUID(), area, nombre, valor, periodo, fuente);\n    }\n\n    /** Un indicador cuya fuente no se actualizó dentro del umbral se marca como desactualizado. */\n    public boolean desactualizado(Instant ahora, Duration umbral) {\n        return fuenteActualizadaUtc.isBefore(ahora.minus(umbral));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/IndicadorConsolidado.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Foto de un indicador dentro de un reporte. Al cerrar el reporte no cambia.\n *\n * @param id componente de tipo {@code UUID}.\n * @param area componente de tipo {@code Area}.\n * @param nombre componente de tipo {@code String}.\n * @param valor componente de tipo {@code BigDecimal}.\n * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n * @param desactualizado componente de tipo {@code boolean}.\n */\npublic record IndicadorConsolidado(UUID id, Area area, String nombre, BigDecimal valor,\n                                   Instant fuenteActualizadaUtc, boolean desactualizado) {\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/IndicadorRepositorio.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.util.List;\n\n/** Puerto para guardar y consultar indicadores, sin depender de JPA. */\npublic interface IndicadorRepositorio {\n    /** Inserta o actualiza el indicador identificado por área, nombre y periodo. */\n    Indicador guardar(Indicador indicador);\n    /** Indicadores del periodo; si area es null, de todas las áreas. */\n    List<Indicador> buscar(Area area, Periodo periodo);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/Periodo.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.util.regex.Pattern;\n\n/**\n * Periodo mensual (2026-10), trimestral (2026-Q4) o anual (2026).\n *\n * @param clave componente de tipo {@code String}.\n */\npublic record Periodo(String clave) {\n\n    private static final Pattern FORMATO =\n            Pattern.compile(\"^(\\\\d{4}-(0[1-9]|1[0-2])|\\\\d{4}-Q[1-4]|\\\\d{4})$\");\n\n    public Periodo {\n        if (clave == null || !FORMATO.matcher(clave).matches()) {\n            throw new SolicitudInvalidaException(\"Periodo inválido: use AAAA, AAAA-MM o AAAA-Qn\");\n        }\n    }\n\n    /** Crea un periodo a partir de su clave: AAAA-MM, AAAA-Qn o AAAA. Lanza excepción si el formato es inválido. */\n    public static Periodo de(String clave) {\n        return new Periodo(clave);\n    }\n\n    /** Devuelve la clave del periodo, por ejemplo 2026-09. */\n    @Override\n    public String toString() {\n        return clave;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Crea la excepción con el mensaje que se mostrará al cliente. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Crea la excepción con el mensaje de la regla incumplida. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/Reporte.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Reporte de un periodo. BORRADOR se consolida en vivo; al cerrarse, guarda una foto y no vuelve a cambiar. */\npublic class Reporte {\n\n    private final UUID id;\n    private final Periodo periodo;\n    private final Instant creadoUtc;\n    private EstatusReporte estatus;\n    private Instant cerradoUtc;\n    private List<IndicadorConsolidado> indicadoresCerrados;\n\n    /** Constructor privado: los reportes se crean con abrir o reconstruir. */\n    private Reporte(UUID id, Periodo periodo, Instant creadoUtc, EstatusReporte estatus, Instant cerradoUtc,\n                    List<IndicadorConsolidado> indicadoresCerrados) {\n        this.id = id;\n        this.periodo = periodo;\n        this.creadoUtc = creadoUtc;\n        this.estatus = estatus;\n        this.cerradoUtc = cerradoUtc;\n        this.indicadoresCerrados = List.copyOf(indicadoresCerrados);\n    }\n\n    /** Abre un reporte nuevo en BORRADOR para un periodo. */\n    public static Reporte abrir(Periodo periodo, Instant ahora) {\n        return new Reporte(UUID.randomUUID(), periodo, ahora, EstatusReporte.BORRADOR, null, List.of());\n    }\n\n    /** Reconstruye un reporte desde la base de datos sin aplicar reglas. */\n    public static Reporte reconstruir(UUID id, Periodo periodo, Instant creadoUtc, EstatusReporte estatus,\n                                      Instant cerradoUtc, List<IndicadorConsolidado> indicadoresCerrados) {\n        return new Reporte(id, periodo, creadoUtc, estatus, cerradoUtc, indicadoresCerrados);\n    }\n\n    /** Lanza ConflictoException si el reporte ya está cerrado. Toda modificación pasa por aquí. */\n    public void exigirAbierto() {\n        if (estatus == EstatusReporte.CERRADO) {\n            throw new ConflictoException(\"El reporte \" + periodo + \" está cerrado; no admite cambios\");\n        }\n    }\n\n    /** Cierra el reporte con sus indicadores consolidados. Un reporte sin indicadores no se puede cerrar. */\n    public void cerrar(List<IndicadorConsolidado> consolidados, Instant ahora) {\n        exigirAbierto();\n        if (consolidados.isEmpty()) {\n            throw new ReglaDeNegocioException(\"No hay indicadores para cerrar el periodo \" + periodo);\n        }\n        this.estatus = EstatusReporte.CERRADO;\n        this.cerradoUtc = ahora;\n        this.indicadoresCerrados = List.copyOf(consolidados);\n    }\n\n    /** Devuelve el identificador del reporte. */\n    public UUID getId() { return id; }\n    /** Devuelve el periodo del reporte. */\n    public Periodo getPeriodo() { return periodo; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve el estatus del reporte. */\n    public EstatusReporte getEstatus() { return estatus; }\n    /** Devuelve la fecha de cierre en UTC, o nula si sigue abierto. */\n    public Instant getCerradoUtc() { return cerradoUtc; }\n    /** Devuelve los indicadores consolidados al cerrar el reporte. */\n    public List<IndicadorConsolidado> getIndicadoresCerrados() { return indicadoresCerrados; }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/ReporteRepositorio.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar reportes, sin depender de JPA. */\npublic interface ReporteRepositorio {\n    Reporte guardar(Reporte reporte);\n    Optional<Reporte> buscarPorPeriodo(Periodo periodo);\n    Optional<Reporte> buscarPorId(UUID id);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/domain/SolicitudInvalidaException.java": "package com.mx.josesaid.develop.reportes.domain;\n\n/** Datos de forma inválidos. HTTP 400. */\npublic class SolicitudInvalidaException extends RuntimeException {\n    /** Crea la excepción con el motivo de la solicitud inválida. */\n    public SolicitudInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/exportacion/ExportadorCsv.java": "package com.mx.josesaid.develop.reportes.infrastructure.exportacion;\n\nimport com.mx.josesaid.develop.reportes.application.DatosExportacion;\nimport com.mx.josesaid.develop.reportes.application.ExportadorReporte;\nimport com.mx.josesaid.develop.reportes.application.FormatoExportacion;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport java.nio.charset.StandardCharsets;\nimport org.springframework.stereotype.Component;\n\n/** CSV en UTF-8 con BOM para que Excel lo abra con acentos correctos. */\n@Component\npublic class ExportadorCsv implements ExportadorReporte {\n\n    /** Devuelve el formato CSV. */\n    @Override\n    public FormatoExportacion formato() {\n        return FormatoExportacion.CSV;\n    }\n\n    /** Genera el CSV del reporte con una fila por indicador. Los campos con comas o comillas se escapan. */\n    @Override\n    public byte[] exportar(DatosExportacion datos) {\n        StringBuilder csv = new StringBuilder(\"﻿\")\n                .append(\"area,nombre,periodo,valor,fuente_actualizada_utc,desactualizado\\n\");\n        for (IndicadorConsolidado c : datos.indicadores()) {\n            csv.append(escapar(c.area().name())).append(',')\n                    .append(escapar(c.nombre())).append(',')\n                    .append(escapar(datos.periodo())).append(',')\n                    .append(c.valor().toPlainString()).append(',')\n                    .append(c.fuenteActualizadaUtc()).append(',')\n                    .append(c.desactualizado()).append('\\n');\n        }\n        return csv.toString().getBytes(StandardCharsets.UTF_8);\n    }\n\n    /** Escapa un campo CSV: si tiene comas, comillas o saltos de línea, lo encierra en comillas y duplica las comillas internas. */\n    private static String escapar(String valor) {\n        return \"\\\"\" + valor.replace(\"\\\"\", \"\\\"\\\"\") + \"\\\"\";\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/exportacion/ExportadorPdf.java": "package com.mx.josesaid.develop.reportes.infrastructure.exportacion;\n\nimport com.lowagie.text.Document;\nimport com.lowagie.text.DocumentException;\nimport com.lowagie.text.FontFactory;\nimport com.lowagie.text.PageSize;\nimport com.lowagie.text.Paragraph;\nimport com.lowagie.text.Phrase;\nimport com.lowagie.text.pdf.PdfPCell;\nimport com.lowagie.text.pdf.PdfPTable;\nimport com.lowagie.text.pdf.PdfWriter;\nimport com.mx.josesaid.develop.reportes.application.DatosExportacion;\nimport com.mx.josesaid.develop.reportes.application.ExportadorReporte;\nimport com.mx.josesaid.develop.reportes.application.FormatoExportacion;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport java.io.ByteArrayOutputStream;\nimport java.time.format.DateTimeFormatter;\nimport org.springframework.stereotype.Component;\n\n/** PDF horizontal A4 con título, identificador del reporte y tabla de indicadores. */\n@Component\npublic class ExportadorPdf implements ExportadorReporte {\n\n    private static final DateTimeFormatter FECHA = DateTimeFormatter.ISO_INSTANT;\n\n    /** Devuelve el formato PDF. */\n    @Override\n    public FormatoExportacion formato() {\n        return FormatoExportacion.PDF;\n    }\n\n    /** Genera el PDF del reporte con una tabla de indicadores. */\n    @Override\n    public byte[] exportar(DatosExportacion datos) {\n        ByteArrayOutputStream salida = new ByteArrayOutputStream();\n        Document documento = new Document(PageSize.A4.rotate());\n        try {\n            PdfWriter.getInstance(documento, salida);\n            documento.open();\n            documento.add(new Paragraph(\"Reporte ejecutivo \" + datos.periodo(),\n                    FontFactory.getFont(FontFactory.HELVETICA_BOLD, 16)));\n            documento.add(new Paragraph(\"Identificador: \" + datos.reporteId(),\n                    FontFactory.getFont(FontFactory.HELVETICA, 9)));\n            documento.add(new Paragraph(\" \"));\n\n            PdfPTable tabla = new PdfPTable(new float[]{2f, 4f, 2f, 3f, 2f});\n            tabla.setWidthPercentage(100f);\n            for (String cabecera : new String[]{\"Área\", \"Indicador\", \"Valor\", \"Fuente actualizada (UTC)\", \"Estado\"}) {\n                tabla.addCell(new PdfPCell(new Phrase(cabecera, FontFactory.getFont(FontFactory.HELVETICA_BOLD, 10))));\n            }\n            for (IndicadorConsolidado c : datos.indicadores()) {\n                tabla.addCell(celda(c.area().etiqueta()));\n                tabla.addCell(celda(c.nombre()));\n                tabla.addCell(celda(c.valor().toPlainString()));\n                tabla.addCell(celda(FECHA.format(c.fuenteActualizadaUtc())));\n                tabla.addCell(celda(c.desactualizado() ? \"Desactualizado\" : \"Al día\"));\n            }\n            documento.add(tabla);\n        } catch (DocumentException e) {\n            throw new IllegalStateException(\"No se pudo generar el PDF del reporte \" + datos.reporteId(), e);\n        } finally {\n            documento.close();\n        }\n        return salida.toByteArray();\n    }\n\n    /** Crea una celda de la tabla del PDF con el texto indicado. */\n    private static PdfPCell celda(String texto) {\n        return new PdfPCell(new Phrase(texto, FontFactory.getFont(FontFactory.HELVETICA, 9)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/exportacion/ExportadorXlsx.java": "package com.mx.josesaid.develop.reportes.infrastructure.exportacion;\n\nimport com.mx.josesaid.develop.reportes.application.DatosExportacion;\nimport com.mx.josesaid.develop.reportes.application.ExportadorReporte;\nimport com.mx.josesaid.develop.reportes.application.FormatoExportacion;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.io.UncheckedIOException;\nimport org.apache.poi.ss.usermodel.CellStyle;\nimport org.apache.poi.ss.usermodel.Font;\nimport org.apache.poi.ss.usermodel.Row;\nimport org.apache.poi.ss.usermodel.Sheet;\nimport org.apache.poi.xssf.usermodel.XSSFWorkbook;\nimport org.springframework.stereotype.Component;\n\n/** Libro Excel (.xlsx) con una hoja, encabezados en negrita y panel congelado. */\n@Component\npublic class ExportadorXlsx implements ExportadorReporte {\n\n    private static final String[] CABECERAS = {\n            \"Área\", \"Indicador\", \"Periodo\", \"Valor\", \"Fuente actualizada (UTC)\", \"Desactualizado\"};\n\n    /** Devuelve el formato XLSX. */\n    @Override\n    public FormatoExportacion formato() {\n        return FormatoExportacion.XLSX;\n    }\n\n    /** Genera el libro de Excel del reporte con una hoja de indicadores. */\n    @Override\n    public byte[] exportar(DatosExportacion datos) {\n        try (XSSFWorkbook libro = new XSSFWorkbook();\n             ByteArrayOutputStream salida = new ByteArrayOutputStream()) {\n            Sheet hoja = libro.createSheet(\"Reporte \" + datos.periodo());\n\n            Font negrita = libro.createFont();\n            negrita.setBold(true);\n            CellStyle estiloCabecera = libro.createCellStyle();\n            estiloCabecera.setFont(negrita);\n\n            Row cabecera = hoja.createRow(0);\n            for (int i = 0; i < CABECERAS.length; i++) {\n                var celda = cabecera.createCell(i);\n                celda.setCellValue(CABECERAS[i]);\n                celda.setCellStyle(estiloCabecera);\n                hoja.setColumnWidth(i, 22 * 256);\n            }\n\n            int fila = 1;\n            for (IndicadorConsolidado c : datos.indicadores()) {\n                Row r = hoja.createRow(fila++);\n                r.createCell(0).setCellValue(c.area().etiqueta());\n                r.createCell(1).setCellValue(c.nombre());\n                r.createCell(2).setCellValue(datos.periodo());\n                r.createCell(3).setCellValue(c.valor().doubleValue());\n                r.createCell(4).setCellValue(c.fuenteActualizadaUtc().toString());\n                r.createCell(5).setCellValue(c.desactualizado() ? \"Sí\" : \"No\");\n            }\n            hoja.createFreezePane(0, 1);\n\n            libro.write(salida);\n            return salida.toByteArray();\n        } catch (IOException e) {\n            throw new UncheckedIOException(\"No se pudo generar el XLSX del reporte \" + datos.reporteId(), e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/mensajeria/ListenerIndicadores.java": "package com.mx.josesaid.develop.reportes.infrastructure.mensajeria;\n\nimport com.mx.josesaid.develop.reportes.application.ReportesService;\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe indicadores de las áreas por Kafka. Un mensaje inválido o que viola una regla\n * (por ejemplo, periodo cerrado) se registra y se descarta; no se reintenta indefinidamente.\n */\n@Component\npublic class ListenerIndicadores {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerIndicadores.class);\n\n    private final ReportesService servicio;\n    private final ObjectMapper mapper;\n\n    /** Recibe el servicio de reportes y el lector JSON de los mensajes de Kafka. */\n    public ListenerIndicadores(ReportesService servicio, ObjectMapper mapper) {\n        this.servicio = servicio;\n        this.mapper = mapper;\n    }\n\n    /** Registra el indicador del mensaje. Un mensaje inválido o que viola una regla se registra en el log y se descarta, sin reintentos infinitos. */\n    @KafkaListener(topics = \"${reportes.indicadores.topico:indicadores-areas}\", groupId = \"reportes-ejecutivos-ms\")\n    public void recibir(String mensaje) {\n        try {\n            IndicadorEvento e = mapper.readValue(mensaje, IndicadorEvento.class);\n            servicio.registrarIndicador(Area.valueOf(e.area()), e.nombre(), Periodo.de(e.periodo()),\n                    e.valor(), e.fuenteActualizadaUtc());\n        } catch (RuntimeException e) {\n            log.warn(\"Indicador descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato del mensaje que publica cada área.\n     *\n     * @param area componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param periodo componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.reportes.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el identificador del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el payload JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.reportes.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.reportes.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.reportes.application.EventoDominio;\nimport com.mx.josesaid.develop.reportes.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el lector JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. Así un evento nunca se pierde si la transacción sí se confirma. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.reportes.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"reportes.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes del outbox. Si el envío falla, deja el evento para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${reportes.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/IndicadorConsolidadoEntity.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Foto de un indicador dentro del reporte cerrado. Sin versión: nunca se modifica después del cierre. */\n@Entity\n@Table(name = \"reporte_indicadores\")\npublic class IndicadorConsolidadoEntity {\n\n    @Id\n    private UUID id;\n\n    @ManyToOne(fetch = FetchType.LAZY, optional = false)\n    @JoinColumn(name = \"reporte_id\", nullable = false, updatable = false)\n    private ReporteEntity reporte;\n\n    @Column(nullable = false)\n    private int posicion;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 40)\n    private Area area;\n\n    @Column(nullable = false, length = 120)\n    private String nombre;\n\n    @Column(nullable = false, precision = 18, scale = 4)\n    private BigDecimal valor;\n\n    @Column(name = \"fuente_actualizada_utc\", nullable = false)\n    private Instant fuenteActualizadaUtc;\n\n    @Column(nullable = false)\n    private boolean desactualizado;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected IndicadorConsolidadoEntity() {\n    }\n\n    IndicadorConsolidadoEntity(ReporteEntity reporte, int posicion, IndicadorConsolidado c) {\n        this.id = c.id();\n        this.reporte = reporte;\n        this.posicion = posicion;\n        this.area = c.area();\n        this.nombre = c.nombre();\n        this.valor = c.valor();\n        this.fuenteActualizadaUtc = c.fuenteActualizadaUtc();\n        this.desactualizado = c.desactualizado();\n    }\n\n    /** Devuelve el identificador del indicador consolidado. */\n    UUID getId() {\n        return id;\n    }\n\n    /** Convierte la fila en el objeto del dominio. */\n    IndicadorConsolidado aDominio() {\n        return new IndicadorConsolidado(id, area, nombre, valor, fuenteActualizadaUtc, desactualizado);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/IndicadorEntity.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.Indicador;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Fila de la tabla de indicadores. Guarda el área, el nombre, el periodo y el valor. */\n@Entity\n@Table(name = \"indicadores\")\npublic class IndicadorEntity {\n\n    @Id\n    private UUID id;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 40)\n    private Area area;\n\n    @Column(nullable = false, length = 120)\n    private String nombre;\n\n    @Column(nullable = false, length = 10)\n    private String periodo;\n\n    @Column(nullable = false, precision = 18, scale = 4)\n    private BigDecimal valor;\n\n    @Column(name = \"fuente_actualizada_utc\", nullable = false)\n    private Instant fuenteActualizadaUtc;\n\n    @Version\n    private Long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected IndicadorEntity() {\n    }\n\n    /** Crea una fila a partir de un indicador del dominio. */\n    static IndicadorEntity nuevo(Indicador i) {\n        IndicadorEntity e = new IndicadorEntity();\n        e.id = i.id();\n        e.actualizar(i);\n        return e;\n    }\n\n    /** Actualiza la fila con los datos de un indicador del dominio. */\n    void actualizar(Indicador i) {\n        this.area = i.area();\n        this.nombre = i.nombre();\n        this.periodo = i.periodo().clave();\n        this.valor = i.valor();\n        this.fuenteActualizadaUtc = i.fuenteActualizadaUtc();\n    }\n\n    /** Convierte la fila en el objeto del dominio. */\n    Indicador aDominio() {\n        return new Indicador(id, area, nombre, valor, Periodo.de(periodo), fuenteActualizadaUtc);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/IndicadorJpaRepository.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\nimport org.springframework.data.jpa.repository.JpaSpecificationExecutor;\n\n/** Acceso a la tabla de indicadores con Spring Data JPA y consultas por especificación. */\npublic interface IndicadorJpaRepository extends JpaRepository<IndicadorEntity, UUID>, JpaSpecificationExecutor<IndicadorEntity> {\n\n    /** Busca el indicador de un área, nombre y periodo. Lo usa la regla de que un indicador se actualiza en vez de duplicarse. */\n    Optional<IndicadorEntity> findByAreaAndNombreAndPeriodo(\n            com.mx.josesaid.develop.reportes.domain.Area area, String nombre, String periodo);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/IndicadorRepositorioJpa.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.Indicador;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorRepositorio;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport jakarta.persistence.criteria.Predicate;\nimport java.util.ArrayList;\nimport java.util.List;\nimport org.springframework.data.jpa.domain.Specification;\nimport org.springframework.stereotype.Repository;\n\n/** Implementa el puerto de indicadores con JPA. */\n@Repository\npublic class IndicadorRepositorioJpa implements IndicadorRepositorio {\n\n    private final IndicadorJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de indicadores. */\n    public IndicadorRepositorioJpa(IndicadorJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un indicador. Si ya existe para el área, nombre y periodo, lo actualiza. */\n    @Override\n    public Indicador guardar(Indicador indicador) {\n        IndicadorEntity e = jpa.findByAreaAndNombreAndPeriodo(indicador.area(), indicador.nombre(),\n                        indicador.periodo().clave())\n                .map(existente -> {\n                    existente.actualizar(indicador);\n                    return existente;\n                })\n                .orElseGet(() -> IndicadorEntity.nuevo(indicador));\n        return jpa.save(e).aDominio();\n    }\n\n    /** Busca los indicadores de un área y periodo. */\n    @Override\n    public List<Indicador> buscar(Area area, Periodo periodo) {\n        Specification<IndicadorEntity> spec = (raiz, consulta, cb) -> {\n            List<Predicate> condiciones = new ArrayList<>();\n            condiciones.add(cb.equal(raiz.get(\"periodo\"), periodo.clave()));\n            if (area != null) {\n                condiciones.add(cb.equal(raiz.get(\"area\"), area));\n            }\n            return cb.and(condiciones.toArray(new Predicate[0]));\n        };\n        return jpa.findAll(spec).stream().map(IndicadorEntity::aDominio).toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/ReporteEntity.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.reportes.domain.EstatusReporte;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport com.mx.josesaid.develop.reportes.domain.Reporte;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.OrderBy;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.time.Instant;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\nimport java.util.stream.Collectors;\n\n/** Fila de la tabla de reportes con su periodo, estatus y fechas. */\n@Entity\n@Table(name = \"reportes\")\npublic class ReporteEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, unique = true, length = 10)\n    private String periodo;\n\n    @Enumerated(EnumType.STRING)\n    @Column(nullable = false, length = 10)\n    private EstatusReporte estatus;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"cerrado_utc\")\n    private Instant cerradoUtc;\n\n    @Version\n    private Long version;\n\n    @OneToMany(mappedBy = \"reporte\", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)\n    @OrderBy(\"posicion ASC\")\n    private List<IndicadorConsolidadoEntity> indicadores = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ReporteEntity() {\n    }\n\n    /** Crea una fila a partir de un reporte del dominio. */\n    static ReporteEntity nuevo(Reporte r) {\n        ReporteEntity e = new ReporteEntity();\n        e.id = r.getId();\n        e.actualizar(r);\n        return e;\n    }\n\n    /** Solo agrega la foto del cierre una vez; los campos del reporte se actualizan al cerrar. */\n    void actualizar(Reporte r) {\n        this.periodo = r.getPeriodo().clave();\n        this.estatus = r.getEstatus();\n        this.creadoUtc = r.getCreadoUtc();\n        this.cerradoUtc = r.getCerradoUtc();\n        Set<UUID> existentes = indicadores.stream().map(IndicadorConsolidadoEntity::getId).collect(Collectors.toSet());\n        List<IndicadorConsolidado> consolidados = r.getIndicadoresCerrados();\n        for (int i = 0; i < consolidados.size(); i++) {\n            if (!existentes.contains(consolidados.get(i).id())) {\n                indicadores.add(new IndicadorConsolidadoEntity(this, i, consolidados.get(i)));\n            }\n        }\n    }\n\n    /** Convierte la fila en el objeto del dominio. */\n    Reporte aDominio() {\n        return Reporte.reconstruir(id, Periodo.de(periodo), creadoUtc, estatus, cerradoUtc,\n                indicadores.stream().map(IndicadorConsolidadoEntity::aDominio).toList());\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/ReporteJpaRepository.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de reportes con Spring Data JPA. */\npublic interface ReporteJpaRepository extends JpaRepository<ReporteEntity, UUID> {\n\n    Optional<ReporteEntity> findByPeriodo(String periodo);\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/infrastructure/persistence/ReporteRepositorioJpa.java": "package com.mx.josesaid.develop.reportes.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.reportes.domain.Periodo;\nimport com.mx.josesaid.develop.reportes.domain.Reporte;\nimport com.mx.josesaid.develop.reportes.domain.ReporteRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Repository;\n\n/** Implementa el puerto de reportes con JPA. */\n@Repository\npublic class ReporteRepositorioJpa implements ReporteRepositorio {\n\n    private final ReporteJpaRepository jpa;\n\n    /** Recibe el repositorio JPA de reportes. */\n    public ReporteRepositorioJpa(ReporteJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un reporte y devuelve la versión persistida. */\n    @Override\n    public Reporte guardar(Reporte reporte) {\n        ReporteEntity e = jpa.findById(reporte.getId())\n                .map(existente -> {\n                    existente.actualizar(reporte);\n                    return existente;\n                })\n                .orElseGet(() -> ReporteEntity.nuevo(reporte));\n        return jpa.save(e).aDominio();\n    }\n\n    /** Busca un reporte por periodo. */\n    @Override\n    public Optional<Reporte> buscarPorPeriodo(Periodo periodo) {\n        return jpa.findByPeriodo(periodo.clave()).map(ReporteEntity::aDominio);\n    }\n\n    /** Busca un reporte por identificador. */\n    @Override\n    public Optional<Reporte> buscarPorId(UUID id) {\n        return jpa.findById(id).map(ReporteEntity::aDominio);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.reportes.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.reportes.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"reportes-ejecutivos-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.reportes.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/reportes/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.reportes.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/api/ReportesControladorAutorizacionTest.java": "package com.mx.josesaid.develop.reportes.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.reportes.application.ReportesService;\nimport com.mx.josesaid.develop.reportes.config.SeguridadConfig;\nimport java.util.List;\nimport org.assertj.core.api.Assertions;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de ReportesControlador.\n * JEFE_AREA lleva el claim \"area\" porque el controlador lo usa para acotar indicadores.\n */\n@WebMvcTest(ReportesControlador.class)\n@Import({SeguridadConfig.class, ReportesControladorAutorizacionTest.Configuracion.class})\nclass ReportesControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String INDICADOR = \"{\\\"area\\\":\\\"FINANZAS_CONTABILIDAD\\\",\\\"nombre\\\":\\\"Ventas\\\",\"\n            + \"\\\"periodo\\\":\\\"2026-10\\\",\\\"valor\\\":100,\\\"fuenteActualizadaUtc\\\":\\\"2026-11-01T00:00:00Z\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ReportesService servicio;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO).claim(\"area\", \"VENTAS_ATENCION_CLIENTES\"))\n                .authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void registrarIndicador() throws Exception {\n        MockHttpServletRequestBuilder req = post(\"/v1/indicadores\").contentType(MediaType.APPLICATION_JSON).content(INDICADOR);\n        permitido(peticion(req, \"DIRECCION\"), \"POST indicadores\", \"DIRECCION\");\n        denegado(peticion(post(\"/v1/indicadores\").contentType(MediaType.APPLICATION_JSON).content(INDICADOR), \"JEFE_AREA\"));\n    }\n\n    @Test\n    void consultarIndicadores() throws Exception {\n        String ruta = \"/v1/indicadores?periodo=2026-10\";\n        permitido(peticion(get(ruta), \"DIRECCION\"), \"GET indicadores\", \"DIRECCION\");\n        permitido(peticion(get(ruta), \"JEFE_AREA\"), \"GET indicadores\", \"JEFE_AREA\");\n        denegado(peticion(get(ruta), \"FINANZAS\"));\n    }\n\n    @Test\n    void consultarReporte() throws Exception {\n        String ruta = \"/v1/reportes/2026-10\";\n        permitido(peticion(get(ruta), \"DIRECCION\"), \"GET reporte\", \"DIRECCION\");\n        permitido(peticion(get(ruta), \"JEFE_AREA\"), \"GET reporte\", \"JEFE_AREA\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void cerrarReporte() throws Exception {\n        String ruta = \"/v1/reportes/2026-10/cierre\";\n        permitido(peticion(post(ruta), \"DIRECCION\"), \"POST cierre\", \"DIRECCION\");\n        denegado(peticion(post(ruta), \"JEFE_AREA\"));\n    }\n\n    @Test\n    void exportarReporte() throws Exception {\n        String ruta = \"/v1/reportes/\" + ID + \"/exportacion\";\n        permitido(peticion(get(ruta), \"DIRECCION\"), \"GET exportacion\", \"DIRECCION\");\n        denegado(peticion(get(ruta), \"JEFE_AREA\"));\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(peticion(get(\"/v1/reportes/2026-10\"), \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/api/ReportesControladorValidacionTest.java": "package com.mx.josesaid.develop.reportes.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.reportes.application.ReportesService;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(ReportesControlador.class)\n@Import(ReportesControladorValidacionTest.Configuracion.class)\nclass ReportesControladorValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ReportesService servicio;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @Test\n    void parametroDemasiadoLargoDa400() throws Exception {\n        mvc.perform(get(\"/v1/indicadores\").param(\"periodo\", \"A\".repeat(21))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_DIRECCION\"))))\n                .andExpect(status().isBadRequest());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/api/ReportesIT.java": "package com.mx.josesaid.develop.reportes.api;\n\nimport static org.hamcrest.Matchers.containsString;\nimport static org.hamcrest.Matchers.hasItem;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Instant;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.ResultActions;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"reportes.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass ReportesIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void indicadoresCierreYExportacionFuncionanExtremoAExtremo() throws Exception {\n        registrar(\"Órdenes cerradas\", \"OPERACIONES\", Instant.now().toString(), \"12.5\").andExpect(status().isCreated());\n        registrar(\"Cartera vencida\", \"FINANZAS_CONTABILIDAD\", \"2020-01-01T00:00:00Z\", \"3\").andExpect(status().isCreated());\n\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$[?(@.nombre=='Cartera vencida')].desactualizado\").value(hasItem(true)))\n                .andExpect(jsonPath(\"$[?(@.nombre=='Órdenes cerradas')].desactualizado\").value(hasItem(false)));\n\n        MvcResult reporte = mvc.perform(get(\"/v1/reportes/2026-10\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"BORRADOR\"))\n                .andReturn();\n        String id = JsonPath.read(reporte.getResponse().getContentAsString(), \"$.id\");\n\n        mvc.perform(post(\"/v1/reportes/2026-10/cierre\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CERRADO\"))\n                .andExpect(jsonPath(\"$.indicadores.length()\").value(2));\n\n        // Cerrado: no se cierra otra vez ni admite indicadores nuevos\n        mvc.perform(post(\"/v1/reportes/2026-10/cierre\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isConflict());\n        registrar(\"Ventas del mes\", \"VENTAS_ATENCION_CLIENTES\", Instant.now().toString(), \"99\")\n                .andExpect(status().isConflict());\n\n        mvc.perform(get(\"/v1/reportes/\" + id + \"/exportacion?formato=CSV\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(content().string(containsString(\"Cartera vencida\")));\n        mvc.perform(get(\"/v1/reportes/\" + id + \"/exportacion?formato=PDF\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(content().contentType(\"application/pdf\"));\n        mvc.perform(get(\"/v1/reportes/\" + id + \"/exportacion?formato=XLSX\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(content().contentType(\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\"));\n        mvc.perform(get(\"/v1/reportes/\" + id + \"/exportacion?formato=DOCX\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void rolesPeriodosInvalidosYReportesInexistentes() throws Exception {\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-10\").with(rol(\"ALMACEN\")))\n                .andExpect(status().isForbidden());\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-13\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isBadRequest());\n        mvc.perform(get(\"/v1/reportes/2024-01\").with(rol(\"DIRECCION\")))\n                .andExpect(status().isNotFound());\n    }\n\n    @Test\n    void jefeDeAreaSoloConsultaSuArea() throws Exception {\n        registrarEn(\"2026-09\", \"Ventas\", \"VENTAS_ATENCION_CLIENTES\", Instant.now().toString(), \"5\")\n                .andExpect(status().isCreated());\n        registrarEn(\"2026-09\", \"Cartera\", \"FINANZAS_CONTABILIDAD\", Instant.now().toString(), \"7\")\n                .andExpect(status().isCreated());\n\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-09\").with(jefe(\"VENTAS_ATENCION_CLIENTES\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.length()\").value(1))\n                .andExpect(jsonPath(\"$[0].nombre\").value(\"Ventas\"));\n\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-09&area=FINANZAS_CONTABILIDAD\")\n                        .with(jefe(\"VENTAS_ATENCION_CLIENTES\")))\n                .andExpect(status().isForbidden());\n\n        mvc.perform(get(\"/v1/indicadores?periodo=2026-09&area=VENTAS_ATENCION_CLIENTES\")\n                        .with(jefe(\"VENTAS_ATENCION_CLIENTES\")))\n                .andExpect(status().isOk());\n\n        mvc.perform(get(\"/v1/reportes/2026-09\").with(jefe(\"VENTAS_ATENCION_CLIENTES\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.indicadores.length()\").value(1));\n\n        // Un jefe no carga ni cierra\n        registrarEn(\"2026-09\", \"Otra\", \"VENTAS_ATENCION_CLIENTES\", Instant.now().toString(), \"1\")\n                .andExpect(status().isForbidden());\n        mvc.perform(post(\"/v1/reportes/2026-09/cierre\").with(jefe(\"VENTAS_ATENCION_CLIENTES\")))\n                .andExpect(status().isForbidden());\n    }\n\n    private ResultActions registrarEn(String periodo, String nombre, String area, String fuente, String valor)\n            throws Exception {\n        String cuerpo = \"\"\"\n                {\"area\":\"%s\",\"nombre\":\"%s\",\"periodo\":\"%s\",\"valor\":%s,\"fuenteActualizadaUtc\":\"%s\"}\n                \"\"\".formatted(area, nombre, periodo, valor, fuente);\n        RequestPostProcessor quien = nombre.equals(\"Otra\") ? jefe(area) : rol(\"DIRECCION\");\n        return mvc.perform(post(\"/v1/indicadores\").with(quien)\n                .contentType(\"application/json\").content(cuerpo));\n    }\n\n    private static RequestPostProcessor jefe(String area) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_JEFE_AREA\"))\n                .jwt(j -> j.claim(\"area\", area));\n    }\n\n    private ResultActions registrar(String nombre, String area, String fuente, String valor) throws Exception {\n        String cuerpo = \"\"\"\n                {\"area\":\"%s\",\"nombre\":\"%s\",\"periodo\":\"2026-10\",\"valor\":%s,\"fuenteActualizadaUtc\":\"%s\"}\n                \"\"\".formatted(area, nombre, valor, fuente);\n        return mvc.perform(post(\"/v1/indicadores\").with(rol(\"DIRECCION\"))\n                .contentType(\"application/json\").content(cuerpo));\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/domain/PeriodoTest.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport static org.junit.jupiter.api.Assertions.assertThrows;\n\nimport org.junit.jupiter.api.Test;\n\nclass PeriodoTest {\n\n    @Test\n    void aceptaMensualTrimestralYAnual() {\n        Periodo.de(\"2026-10\");\n        Periodo.de(\"2026-Q4\");\n        Periodo.de(\"2026\");\n    }\n\n    @Test\n    void rechazaFormatosInvalidos() {\n        assertThrows(SolicitudInvalidaException.class, () -> Periodo.de(\"2026-13\"));\n        assertThrows(SolicitudInvalidaException.class, () -> Periodo.de(\"2026-Q5\"));\n        assertThrows(SolicitudInvalidaException.class, () -> Periodo.de(\"octubre\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/domain/ReporteTest.java": "package com.mx.josesaid.develop.reportes.domain;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.math.BigDecimal;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass ReporteTest {\n\n    private static final Periodo OCTUBRE = Periodo.de(\"2026-10\");\n    private static final Instant AHORA = Instant.parse(\"2026-10-29T12:00:00Z\");\n\n    private static IndicadorConsolidado consolidado(boolean desactualizado) {\n        return new IndicadorConsolidado(UUID.randomUUID(), Area.OPERACIONES, \"Órdenes cerradas\",\n                BigDecimal.TEN, AHORA, desactualizado);\n    }\n\n    @Test\n    void indicadorSinFuenteRecienteQuedaDesactualizado() {\n        Indicador viejo = Indicador.nuevo(Area.FINANZAS_CONTABILIDAD, \"Cartera vencida\", OCTUBRE,\n                BigDecimal.ONE, Instant.parse(\"2020-01-01T00:00:00Z\"));\n        Indicador fresco = Indicador.nuevo(Area.OPERACIONES, \"Órdenes\", OCTUBRE, BigDecimal.ONE, AHORA);\n        assertTrue(viejo.desactualizado(AHORA, Duration.ofDays(7)));\n        assertFalse(fresco.desactualizado(AHORA, Duration.ofDays(7)));\n    }\n\n    @Test\n    void cerrarGuardaLaFotoYNoSePuedeVolverACerrar() {\n        Reporte r = Reporte.abrir(OCTUBRE, AHORA);\n        r.cerrar(List.of(consolidado(false)), AHORA);\n        assertEquals(EstatusReporte.CERRADO, r.getEstatus());\n        assertEquals(1, r.getIndicadoresCerrados().size());\n        assertThrows(ConflictoException.class, () -> r.cerrar(List.of(consolidado(false)), AHORA));\n    }\n\n    @Test\n    void unReporteCerradoNoAdmiteCambios() {\n        Reporte r = Reporte.abrir(OCTUBRE, AHORA);\n        r.cerrar(List.of(consolidado(true)), AHORA);\n        assertThrows(ConflictoException.class, r::exigirAbierto);\n    }\n\n    @Test\n    void noSeCierraUnPeriodoSinIndicadores() {\n        Reporte r = Reporte.abrir(OCTUBRE, AHORA);\n        assertThrows(ReglaDeNegocioException.class, () -> r.cerrar(List.of(), AHORA));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/reportes/infrastructure/exportacion/ExportacionTest.java": "package com.mx.josesaid.develop.reportes.infrastructure.exportacion;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertThrows;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport com.mx.josesaid.develop.reportes.application.DatosExportacion;\nimport com.mx.josesaid.develop.reportes.application.FormatoExportacion;\nimport com.mx.josesaid.develop.reportes.domain.Area;\nimport com.mx.josesaid.develop.reportes.domain.IndicadorConsolidado;\nimport com.mx.josesaid.develop.reportes.domain.SolicitudInvalidaException;\nimport java.io.ByteArrayInputStream;\nimport java.math.BigDecimal;\nimport java.nio.charset.StandardCharsets;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.apache.poi.xssf.usermodel.XSSFWorkbook;\nimport org.junit.jupiter.api.Test;\n\nclass ExportacionTest {\n\n    private static DatosExportacion datos() {\n        UUID id = UUID.randomUUID();\n        return new DatosExportacion(id, \"2026-10\", List.of(\n                new IndicadorConsolidado(UUID.randomUUID(), Area.OPERACIONES, \"Órdenes cerradas\",\n                        new BigDecimal(\"12.50\"), Instant.parse(\"2026-10-29T10:00:00Z\"), false),\n                new IndicadorConsolidado(UUID.randomUUID(), Area.FINANZAS_CONTABILIDAD, \"Cobranza \\\"neta\\\"\",\n                        new BigDecimal(\"3\"), Instant.parse(\"2026-09-01T00:00:00Z\"), true)));\n    }\n\n    @Test\n    void csvTieneCabeceraYFilasConEscape() {\n        String csv = new String(new ExportadorCsv().exportar(datos()), StandardCharsets.UTF_8);\n        assertTrue(csv.contains(\"area,nombre,periodo,valor,fuente_actualizada_utc,desactualizado\"));\n        assertTrue(csv.contains(\"\\\"OPERACIONES\\\",\\\"Órdenes cerradas\\\",\\\"2026-10\\\",12.50\"));\n        assertTrue(csv.contains(\"\\\"Cobranza \\\"\\\"neta\\\"\\\"\\\"\"));\n    }\n\n    @Test\n    void pdfEmpiezaConCabeceraDePdf() {\n        byte[] pdf = new ExportadorPdf().exportar(datos());\n        assertEquals(\"%PDF-\", new String(pdf, 0, 5, StandardCharsets.US_ASCII));\n        assertTrue(pdf.length > 1000);\n    }\n\n    @Test\n    void xlsxTieneEncabezadosYValoresNumericos() throws Exception {\n        byte[] xlsx = new ExportadorXlsx().exportar(datos());\n        try (XSSFWorkbook libro = new XSSFWorkbook(new ByteArrayInputStream(xlsx))) {\n            var hoja = libro.getSheetAt(0);\n            assertEquals(\"Área\", hoja.getRow(0).getCell(0).getStringCellValue());\n            assertEquals(\"Operaciones\", hoja.getRow(1).getCell(0).getStringCellValue());\n            assertEquals(\"Órdenes cerradas\", hoja.getRow(1).getCell(1).getStringCellValue());\n            assertEquals(12.5, hoja.getRow(1).getCell(3).getNumericCellValue());\n            assertEquals(\"Sí\", hoja.getRow(2).getCell(5).getStringCellValue());\n        }\n    }\n\n    @Test\n    void formatoEsInsensibleAMayusculasYRechazaOtros() {\n        assertEquals(FormatoExportacion.PDF, FormatoExportacion.desde(\"pdf\"));\n        assertEquals(FormatoExportacion.XLSX, FormatoExportacion.desde(\"Xlsx\"));\n        assertThrows(SolicitudInvalidaException.class, () -> FormatoExportacion.desde(\"DOCX\"));\n        assertThrows(SolicitudInvalidaException.class, () -> FormatoExportacion.desde(null));\n    }\n}\n"};
